😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀😀","proposedChanges":[],"nextTest":"","reviewState":"draft","reviewedAt":null}');
CREATE FUNCTION firstten_policy_test.gg_id(n integer)RETURNS uuid LANGUAGE sql IMMUTABLE AS $$SELECT('f2700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
CREATE FUNCTION firstten_policy_test.gg_client()RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT encode(sha256(convert_to('firstten-cls009-growth-fixture-client-v1','UTF8')),'hex')$$;
CREATE FUNCTION firstten_policy_test.gg_session(k text)RETURNS text LANGUAGE sql STABLE AS $$SELECT result->>'sessionToken'FROM firstten_policy_test.gg_results WHERE label=k$$;
CREATE FUNCTION firstten_policy_test.gg_doc(k text)RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT document FROM firstten_policy_test.gg_docs WHERE label=k$$;
CREATE FUNCTION firstten_policy_test.gg_valid(d jsonb)RETURNS boolean LANGUAGE plpgsql AS $$BEGIN PERFORM firstten_private.normalize_guest_growth(d);RETURN true;EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.gg_id(integer),firstten_policy_test.gg_session(text),firstten_policy_test.gg_doc(text),firstten_policy_test.gg_client()TO authenticated,service_role;
SELECT is(firstten_private.guest_growth_option_key(chr(key::integer)),value#>>'{}','Pinned Unicode17 mapping: '||key)FROM jsonb_each(firstten_private.guest_growth_option_case_data()->'lower');
SELECT is(firstten_private.guest_growth_option_key(x),expected,'Contextual Sigma including Cased+Ignorable: '||x)FROM(VALUES(U&'\0345Σ',U&'\0345σ'),(U&'AΣ\0345',U&'aς\0345'),(U&'A\0345Σ',U&'a\0345ς'),(U&'AΣ\0345B',U&'aσ\0345b'),(U&'\0130',U&'i\0307'))v(x,expected);
SELECT is(firstten_policy_test.gg_valid(document),valid,'SQL strict corpus: '||label)FROM firstten_policy_test.gg_docs ORDER BY label;
SELECT is(firstten_private.normalize_guest_growth(document),document,'SQL preserves valid authored values: '||label)FROM firstten_policy_test.gg_docs WHERE valid ORDER BY label;
SELECT ok(NOT has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE'),'closed growth table '||r||' / '||t)FROM unnest(ARRAY['anon','authenticated','service_role'])r CROSS JOIN unnest(ARRAY['firstten_private.guest_growth_artifacts','firstten_private.guest_growth_versions','firstten_private.guest_growth_reference_edges','firstten_private.guest_growth_operations'])t;
SELECT ok(NOT has_function_privilege(r,'public.get_guest_growth_authority(text)','EXECUTE'),'tiny authority denies direct '||r)FROM unnest(ARRAY['anon','authenticated'])r;
SELECT ok(NOT has_function_privilege('authenticated','public.save_guest_growth_artifact(text,uuid,text,bigint,uuid,boolean,jsonb)','EXECUTE'),'account role cannot impersonate guest');
SELECT ok(NOT has_function_privilege('service_role','firstten_private.normalize_guest_growth(jsonb)','EXECUTE'),'private validator is closed');
SELECT ok(NOT has_function_privilege('service_role','firstten_private.guest_growth_hash(jsonb)','EXECUTE'),'private canonical hash stays closed to service role');
CREATE FUNCTION firstten_policy_test.gg_require_admission(k text)RETURNS void LANGUAGE plpgsql AS $$
DECLARE receipt jsonb;
BEGIN
 SELECT result INTO receipt FROM firstten_policy_test.gg_results WHERE label=k;
 IF receipt->>'ok'IS DISTINCT FROM'true'THEN RAISE EXCEPTION 'Growth fixture admission failed at %: %',k,coalesce(receipt->>'code','invalid-receipt');END IF;
 IF k='entry'THEN
  IF coalesce(receipt->>'token','')!~'^[a-f0-9]{64}$'THEN RAISE EXCEPTION 'Growth entry fixture returned no capability';END IF;
 ELSE
  IF coalesce(receipt->>'sessionToken','')!~'^[a-f0-9]{64}$'OR receipt#>>'{data,classId}'IS DISTINCT FROM firstten_policy_test.gg_id(1)::text THEN RAISE EXCEPTION 'Growth session fixture returned no valid scoped capability for %',k;END IF;
 END IF;
END $$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.gg_require_admission(text)TO authenticated,service_role;
SELECT firstten_policy_test.set_actor('owner_a');SET LOCAL ROLE authenticated;
