CREATE FUNCTION firstten_policy_test.gg_scope()RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT jsonb_build_object('classId',v->'classId','teamId',v->'teamId','principalId',v->'principalId','accessExpiresAt',v->'accessExpiresAt','contextHash',encode(sha256(convert_to(firstten_private.guest_growth_json(v-ARRAY['classRevision','teamGeneration','principalGeneration']),'UTF8')),'hex'))FROM(SELECT firstten_private.guest_growth_authority(p)v FROM public.class_guest_principals p WHERE id=(SELECT(result#>>'{data,principalId}')::uuid FROM firstten_policy_test.gg_results WHERE label='a'))x$$;
CREATE FUNCTION firstten_policy_test.gg_sources()RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT jsonb_agg(jsonb_build_object('state','saved','artifactId',a.id,'revision',a.current_revision,'kind',a.kind,'audience',a.audience,'authorPrincipalId',a.author_principal_id,'recordHash',encode(sha256(convert_to(firstten_private.guest_growth_json(firstten_private.guest_growth_record(a,a.current_revision)),'UTF8')),'hex'))ORDER BY a.id)FROM firstten_private.guest_growth_artifacts a WHERE a.id BETWEEN firstten_policy_test.gg_id(200)AND firstten_policy_test.gg_id(249)$$;
