-- Direct fixture fills are explicit superuser test setup, never a product API or fabricated account.
CREATE FUNCTION firstten_policy_test.gg_fill(p_mode text,p_count integer,p_heavy boolean)RETURNS void LANGUAGE plpgsql AS $$
DECLARE i integer;j integer;author uuid;team uuid;owner uuid;d jsonb;
BEGIN
 SELECT user_id INTO owner FROM public.classes WHERE id=firstten_policy_test.gg_id(1);
 d:=firstten_policy_test.gg_doc('blank_learning');IF p_heavy THEN d:=d||jsonb_build_object('observations',repeat('😀',3000),'interpretation',repeat('😀',3000),'counterevidence',repeat('é',2000),'uncertainty',repeat('é',2000));END IF;
 FOR i IN 1..p_count LOOP
  IF p_mode='class'THEN j:=(i-1)/6+1;team:=firstten_policy_test.gg_id(8000+j);author:=firstten_policy_test.gg_id(9000+j);
   INSERT INTO public.class_teams(id,class_id,issued_by,alias)VALUES(team,firstten_policy_test.gg_id(1),owner,'Fictional class-cap team')ON CONFLICT DO NOTHING;
   INSERT INTO public.class_guest_principals(id,class_id,team_id,issued_by,alias)VALUES(author,firstten_policy_test.gg_id(1),team,owner,'Fictional class-cap learner')ON CONFLICT DO NOTHING;
  ELSE SELECT(result#>>'{data,principalId}')::uuid,(result#>>'{data,teamId}')::uuid INTO author,team FROM firstten_policy_test.gg_results WHERE label='a';END IF;
  INSERT INTO firstten_private.guest_growth_artifacts(id,class_id,team_id,author_principal_id,kind,audience,current_revision)VALUES(firstten_policy_test.gg_id(10000+i),firstten_policy_test.gg_id(1),team,author,'learning',CASE WHEN p_mode='private'THEN'principal_private'ELSE'team_shared'END,CASE WHEN p_heavy THEN 40 ELSE 1 END);
  INSERT INTO firstten_private.guest_growth_versions(artifact_id,revision,document)SELECT firstten_policy_test.gg_id(10000+i),v,d FROM generate_series(1,CASE WHEN p_heavy THEN 40 ELSE 1 END)v;
 END LOOP;
END $$;
SELECT firstten_policy_test.gg_fill('private',8,false);
SET LOCAL ROLE service_role;
SELECT is(public.save_guest_growth_artifact(firstten_policy_test.gg_session('a'),firstten_policy_test.gg_id(400),'principal_private',0,gen_random_uuid(),false,firstten_policy_test.gg_doc('blank_learning'))->>'code','CAPACITY','64 private artifact count is enforced');
RESET ROLE;DELETE FROM firstten_private.guest_growth_artifacts WHERE class_id=firstten_policy_test.gg_id(1)AND id BETWEEN firstten_policy_test.gg_id(10001)AND firstten_policy_test.gg_id(10100);
