RESET ROLE;DELETE FROM firstten_private.guest_growth_artifacts WHERE class_id=firstten_policy_test.gg_id(1)AND id BETWEEN firstten_policy_test.gg_id(10001)AND firstten_policy_test.gg_id(10100);
