SELECT is(public.save_guest_growth_artifact(firstten_policy_test.gg_session('a'),firstten_policy_test.gg_id(101),'principal_private',0,firstten_policy_test.gg_id(1101),false,firstten_policy_test.gg_doc('learning'))->>'ok','true','stable replay remains possible at receipt/history cap without duplicate payload');
