INSERT INTO firstten_policy_test.gg_results VALUES('dependent_export',jsonb_build_object('scope',firstten_policy_test.gg_scope(),'sources',(SELECT jsonb_build_array(jsonb_build_object('state','saved','artifactId',a.id,'revision',a.current_revision,'kind',a.kind,'audience',a.audience,'authorPrincipalId',a.author_principal_id,'recordHash',encode(sha256(convert_to(firstten_private.guest_growth_json(firstten_private.guest_growth_record(a,a.current_revision)),'UTF8')),'hex')))FROM firstten_private.guest_growth_artifacts a WHERE id=firstten_policy_test.gg_id(102))));
