SET LOCAL ROLE service_role;
SELECT is(public.load_guest_growth_artifact(firstten_policy_test.gg_session('recovered'),firstten_policy_test.gg_id(102),2)->>'code','NOT_FOUND','deleted source invalidates dependent load');
SELECT is(public.get_guest_growth_history(firstten_policy_test.gg_session('recovered'),firstten_policy_test.gg_id(102))->>'code','NOT_FOUND','deleted source invalidates all dependent history');
SELECT ok(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.list_guest_growth_artifacts(firstten_policy_test.gg_session('recovered'))->'data'->'items')x WHERE x->>'id'=firstten_policy_test.gg_id(102)::text),'deleted source removes dependent list headers');
SELECT is(public.save_guest_growth_artifact(firstten_policy_test.gg_session('recovered'),firstten_policy_test.gg_id(102),'principal_private',0,firstten_policy_test.gg_id(1102),false,firstten_policy_test.gg_doc('experiment'))->>'code','NOT_FOUND','deleted source invalidates exact replay');
SELECT is(public.authorize_guest_growth_export(firstten_policy_test.gg_session('recovered'),(SELECT result->'scope'FROM firstten_policy_test.gg_results WHERE label='dependent_export'),(SELECT result->'sources'FROM firstten_policy_test.gg_results WHERE label='dependent_export'))->>'code','CHANGED','deleted source invalidates exact PDF descriptor');
RESET ROLE;
DELETE FROM firstten_private.guest_growth_artifacts WHERE id=firstten_policy_test.gg_id(102);
SELECT ok(NOT EXISTS(SELECT 1 FROM firstten_private.guest_growth_versions WHERE artifact_id=firstten_policy_test.gg_id(102)),'whole parent cascade removes its own retained revisions');
UPDATE public.classes SET archived_at=clock_timestamp(),revision=revision+1 WHERE id=firstten_policy_test.gg_id(1);
SET LOCAL ROLE service_role;
SELECT is(public.get_guest_growth_authority(firstten_policy_test.gg_session('recovered'))->>'code','NOT_FOUND','class closure denies authority');
SELECT is(public.load_guest_growth_artifact(firstten_policy_test.gg_session('buddy'),firstten_policy_test.gg_id(120))->>'code','NOT_FOUND','class closure denies team reads');
RESET ROLE;
SELECT ok(NOT EXISTS(SELECT 1 FROM public.class_guest_principals p JOIN auth.users u ON u.id=p.id WHERE p.class_id=firstten_policy_test.gg_id(1)),'no guest principal is a fake auth user');

DELETE FROM public.classes WHERE id=firstten_policy_test.gg_id(1);
SELECT ok(NOT EXISTS(SELECT 1 FROM firstten_private.guest_growth_artifacts WHERE class_id=firstten_policy_test.gg_id(1)),'whole class cascade removes growth namespace without orphaning records');
